import { Component, Emit, Vue } from 'vue-property-decorator';
import { OverlaysEventEmitter } from '../../event-emitter';

@Component({
    name: 'GameInGameFreeze'
})
export default class GameInGameFreeze extends Vue {
    public isVisible: boolean = false;

    public created() {
        this.show = this.show.bind(this);
    }

    public mounted() {
        OverlaysEventEmitter.on('showGameInGameFreeze', this.show, this);
    }

    public beforeDestroy() {
        OverlaysEventEmitter.off('showGameInGameFreeze', this.show, this);
    }

    @Emit('onMyAccount')
    public onMyAccount() {
        this.close();
    }

    @Emit('onLiveChat')
    public onLiveChat() {
        this.close();
    }

    public show() {
        this.isVisible = true;
    }

    public close() {
        this.isVisible = false;
    }
}
